+          connectivity: { connected: true, timestamp: 0 },
+          data: {},
+          metadata: {},
+          shadowVersion: undefined,
+          deviceTimestamp: 0,
+          receivedAt: 0,
+        },
       },
-      { withASecondLiteral: found + 1, withOneMorePropertyRead: found },
     );
+    verify(api);
   });
 });

